const LESSONS = [{"id": "l1", "subject": "Mathe", "grade": 1, "title": "Zahlen bis 20", "explain": ["Mit Zahlen sagst du, wie viele Dinge da sind. Zähle jedes Ding genau einmal.", "Nach 9 kommt 10. Zehn einzelne Einer kannst du zu einem Zehner bündeln."], "example": "14 sind ein Zehner und vier Einer. Lege zehn Steine zusammen und vier daneben.", "tip": "Beim Zählen hilft es, die Dinge nacheinander anzutippen."}, {"id": "l2", "subject": "Mathe", "grade": 1, "title": "Plus: Zusammen wird es mehr", "explain": ["Plus bedeutet: Etwas kommt dazu. Das Zeichen dafür ist +.", "Beginne bei der ersten Zahl und zähle die zweite Zahl weiter."], "example": "Du hast 4 Äpfel und bekommst 3 dazu: 4 + 3 = 7. Zähle von 4 weiter: 5, 6, 7.", "tip": "Beim Plusrechnen darfst du die Zahlen vertauschen: 4 + 3 = 3 + 4."}, {"id": "l3", "subject": "Mathe", "grade": 1, "title": "Minus: Etwas geht weg", "explain": ["Minus bedeutet hier: Du nimmst etwas weg. Das Zeichen dafür ist −.", "Zähle vom Anfang rückwärts oder streiche Dinge durch."], "example": "Von 8 Keksen werden 2 gegessen: 8 − 2 = 6.", "tip": "Plus und Minus gehören zusammen: 6 + 2 = 8, also 8 − 2 = 6."}, {"id": "l4", "subject": "Mathe", "grade": 2, "title": "Zehner und Einer bis 100", "explain": ["Eine zweistellige Zahl hat Zehner und Einer. Die linke Ziffer zeigt die Zehner.", "Beim Rechnen kannst du die Zahlen zerlegen."], "example": "34 + 23 = 30 + 20 + 4 + 3 = 57.", "tip": "Bei 34 hörst du zuerst „vier“, schreibst aber zuerst die 3 für drei Zehner."}, {"id": "l5", "subject": "Mathe", "grade": 2, "title": "Malnehmen verstehen", "explain": ["Malnehmen fasst gleich große Gruppen zusammen. 3 · 4 bedeutet hier: drei Gruppen mit je vier Dingen.", "Du kannst die Gruppen auch als Reihen legen."], "example": "4 + 4 + 4 = 12. Deshalb ist 3 · 4 = 12.", "tip": "Malnehmen ist wiederholtes Addieren gleich großer Mengen."}, {"id": "l6", "subject": "Mathe", "grade": 2, "title": "Teilen verstehen", "explain": ["Beim Teilen verteilst du etwas gleichmäßig. Alle bekommen gleich viel.", "Oder du fragst: Wie viele gleich große Gruppen passen hinein?"], "example": "12 Bonbons für 3 Kinder: 12 : 3 = 4. Jedes Kind bekommt 4 Bonbons.", "tip": "Prüfe mit Malnehmen: 3 · 4 = 12."}, {"id": "l7", "subject": "Mathe", "grade": 3, "title": "Zahlen bis 1.000", "explain": ["Zahlen bestehen aus Stellen: Hundertern, Zehnern und Einern.", "Eine Null hält eine leere Stelle frei."], "example": "507 bedeutet 5 Hunderter, 0 Zehner und 7 Einer. 570 ist eine andere Zahl.", "tip": "Die Stelle einer Ziffer bestimmt ihren Wert."}, {"id": "l8", "subject": "Mathe", "grade": 3, "title": "Teilen mit Rest", "explain": ["Manchmal lässt sich eine Menge nicht vollständig gleichmäßig verteilen.", "Was übrig bleibt, heißt Rest. Der Rest muss kleiner als die Zahl sein, durch die du teilst."], "example": "17 : 5 = 3 Rest 2. Denn 3 · 5 + 2 = 17.", "tip": "Ein Rest von 5 beim Teilen durch 5 wäre noch eine ganze Gruppe."}, {"id": "l9", "subject": "Mathe", "grade": 3, "title": "Längen und Einheiten", "explain": ["Längen zeigen, wie lang etwas ist. Kleine Dinge misst du oft in Zentimetern, große in Metern.", "1 m sind 100 cm. 1 cm sind 10 mm."], "example": "Ein Band von 2 m und 30 cm ist 230 cm lang.", "tip": "Vergleiche Längen erst, wenn sie dieselbe Einheit haben."}, {"id": "l10", "subject": "Mathe", "grade": 4, "title": "Schriftlich addieren und subtrahieren", "explain": ["Schreibe gleiche Stellen untereinander: Einer unter Einer, Zehner unter Zehner.", "Beginne rechts. Beim Addieren werden zehn Einer zu einem Zehner. Beim Subtrahieren kannst du einen Zehner in zehn Einer tauschen."], "example": "278 + 156: 8 + 6 = 14, schreibe 4 und übertrage 1. Dann 7 + 5 + 1 = 13. Schließlich 2 + 1 + 1 = 4. Ergebnis: 434.", "tip": "Ein Überschlag hilft beim Prüfen: 280 + 160 liegt ungefähr bei 440."}, {"id": "l11", "subject": "Mathe", "grade": 4, "title": "Brüche als Teile eines Ganzen", "explain": ["Ein Bruch beschreibt gleich große Teile. Unten steht, in wie viele Teile das Ganze geteilt wurde.", "Oben steht, wie viele Teile du meinst."], "example": "Eine Pizza wird in 4 gleich große Stücke geteilt. 3 Stücke sind 3/4 der Pizza.", "tip": "Bruchteile lassen sich nur direkt vergleichen, wenn klar ist, welches Ganze gemeint ist."}, {"id": "l12", "subject": "Mathe", "grade": 4, "title": "Umfang und Fläche", "explain": ["Der Umfang ist die Länge des Randes. Die Fläche beschreibt, wie viel Platz innen liegt.", "Beim Rechteck rechnest du Umfang = 2 · Länge + 2 · Breite. Fläche = Länge · Breite."], "example": "Ein Rechteck ist 5 cm lang und 3 cm breit: Umfang 16 cm, Fläche 15 cm².", "tip": "Längen haben Einheiten wie cm; Flächen Einheiten wie cm²."}, {"id": "l13", "subject": "Mathe", "grade": 5, "title": "Reihenfolge beim Rechnen", "explain": ["Rechne zuerst Klammern, dann Mal und Geteilt, dann Plus und Minus.", "Gleichrangige Rechenarten rechnest du von links nach rechts."], "example": "3 + 4 · 2 = 11. Aber (3 + 4) · 2 = 14. Und 12 : 3 · 2 = 8.", "tip": "„Punkt vor Strich“ bedeutet: Mal und Geteilt vor Plus und Minus."}, {"id": "l14", "subject": "Mathe", "grade": 5, "title": "Brüche erweitern und kürzen", "explain": ["Du veränderst die Einteilung, aber nicht den Anteil. Beim Erweitern multiplizierst du Zähler und Nenner mit derselben Zahl.", "Beim Kürzen teilst du beide durch dieselbe gemeinsame Zahl. Diese Zahl darf nicht null sein."], "example": "2/3 = 4/6. Sechs kleinere Stücke teilen dasselbe Ganze feiner ein. 6/8 lässt sich zu 3/4 kürzen.", "tip": "Nur oben oder nur unten zu rechnen verändert den Bruchwert."}, {"id": "l15", "subject": "Mathe", "grade": 5, "title": "Winkel verstehen", "explain": ["Ein Winkel beschreibt, wie weit zwei Strahlen auseinanderliegen. Gemessen wird er in Grad.", "Ein rechter Winkel hat 90°, ein gestreckter 180°. Spitze Winkel sind kleiner als 90°, stumpfe liegen zwischen 90° und 180°."], "example": "Die Ecke eines Rechtecks hat 90°. Eine halbe Drehung sind 180°.", "tip": "Lege beim Messen den Mittelpunkt des Geodreiecks auf den Scheitelpunkt."}, {"id": "l16", "subject": "Mathe", "grade": 6, "title": "Dezimalzahlen rechnen", "explain": ["Nach dem Komma stehen Zehntel, Hundertstel und weitere kleinere Stellen.", "Beim Addieren und Subtrahieren schreibst du Komma unter Komma. Du darfst hinten Nullen ergänzen."], "example": "2,5 + 0,37 = 2,50 + 0,37 = 2,87.", "tip": "2,50 und 2,5 haben denselben Wert."}, {"id": "l17", "subject": "Mathe", "grade": 6, "title": "Brüche addieren und multiplizieren", "explain": ["Zum Addieren brauchen Brüche gleiche Nenner. Erweitere zuerst passend; addiere dann die Zähler.", "Beim Multiplizieren rechnest du Zähler mal Zähler und Nenner mal Nenner."], "example": "1/2 + 1/3 = 3/6 + 2/6 = 5/6. Dagegen: 1/2 · 1/3 = 1/6.", "tip": "Beim Addieren werden die Nenner nicht addiert."}, {"id": "l18", "subject": "Mathe", "grade": 6, "title": "Negative Zahlen", "explain": ["Negative Zahlen liegen auf dem Zahlenstrahl links von null. Je weiter links eine Zahl liegt, desto kleiner ist sie.", "Beim Addieren einer positiven Zahl gehst du nach rechts, beim Addieren einer negativen nach links."], "example": "−3 + 5 = 2. Und −3 + (−2) = −5. Deshalb ist −5 kleiner als −3.", "tip": "Das Minuszeichen kann zu einer Zahl gehören oder eine Rechenoperation anzeigen."}, {"id": "l19", "subject": "Mathe", "grade": 7, "title": "Prozentrechnung", "explain": ["Prozent bedeutet „von hundert“. Der Grundwert ist das Ganze, der Prozentwert der betrachtete Teil.", "Prozentwert = Grundwert · Prozentsatz / 100."], "example": "20 % von 60 € sind 60 · 20 / 100 = 12 €. Nach 20 % Rabatt kosten die Waren 48 €.", "tip": "100 % entsprechen dem ganzen Grundwert."}, {"id": "l20", "subject": "Mathe", "grade": 7, "title": "Dreisatz und Proportionalität", "explain": ["Bei proportionalen Größen bleibt der Quotient gleich. Verdoppelst du die eine Größe, verdoppelt sich die andere.", "Rechne erst auf eine Einheit und danach auf die gesuchte Menge."], "example": "3 gleich teure Hefte kosten 6 €. Ein Heft kostet 2 €, fünf Hefte kosten 10 €.", "tip": "Dreisatz passt hier nur, wenn der Stückpreis gleich bleibt."}, {"id": "l21", "subject": "Mathe", "grade": 7, "title": "Gleichungen lösen", "explain": ["Eine Gleichung behauptet: Links und rechts steht derselbe Wert. Die Variable steht für eine unbekannte Zahl.", "Führe auf beiden Seiten dieselbe zulässige Rechenoperation aus, damit die Gleichheit erhalten bleibt."], "example": "3x + 5 = 20. Ziehe beidseits 5 ab: 3x = 15. Teile durch 3: x = 5. Probe: 3 · 5 + 5 = 20.", "tip": "Stelle dir die Gleichung wie eine Waage im Gleichgewicht vor."}, {"id": "l22", "subject": "Mathe", "grade": 8, "title": "Lineare Funktionen", "explain": ["Eine lineare Funktion hat die Form y = m · x + b. Ihr Graph ist eine Gerade.", "m beschreibt die Steigung; b ist der y-Wert bei x = 0."], "example": "Bei y = 2x + 3 liegt der Startpunkt bei (0; 3). Gehst du 1 nach rechts, gehst du 2 nach oben.", "tip": "Eine negative Steigung bedeutet: Die Gerade fällt nach rechts."}, {"id": "l23", "subject": "Mathe", "grade": 8, "title": "Terme und binomische Formeln", "explain": ["Terme beschreiben Rechenvorschriften. Beim Ausmultiplizieren wird jeder Teil einer Klammer mit jedem Teil der anderen multipliziert.", "Daraus folgt (a + b)² = a² + 2ab + b² und (a − b)² = a² − 2ab + b²."], "example": "(x + 3)² = (x + 3)(x + 3) = x² + 6x + 9.", "tip": "(a + b)² ist im Allgemeinen nicht a² + b²."}, {"id": "l24", "subject": "Mathe", "grade": 8, "title": "Wahrscheinlichkeit", "explain": ["Eine Wahrscheinlichkeit beschreibt, wie wahrscheinlich ein Ereignis in einem Modell ist. Sie liegt zwischen 0 und 1.", "Sind alle Ergebnisse gleich wahrscheinlich, gilt: günstige Ergebnisse geteilt durch alle möglichen Ergebnisse."], "example": "Ein fairer Würfel hat 6 gleich wahrscheinliche Seiten. Für eine gerade Zahl sind 2, 4 und 6 günstig: 3/6 = 1/2.", "tip": "Auch nach mehreren Sechsen bleibt beim nächsten unabhängigen fairen Wurf die Chance für eine Sechs 1/6."}, {"id": "l25", "subject": "Mathe", "grade": 9, "title": "Satz des Pythagoras", "explain": ["Im rechtwinkligen Dreieck gilt a² + b² = c². Dabei ist c die Hypotenuse gegenüber dem rechten Winkel.", "Du kannst damit eine fehlende Seitenlänge berechnen."], "example": "Sind die Katheten 3 cm und 4 cm lang, gilt c² = 9 + 16 = 25. Weil eine Länge positiv ist, folgt c = 5 cm.", "tip": "Prüfe zuerst, ob das Dreieck wirklich rechtwinklig ist."}, {"id": "l26", "subject": "Mathe", "grade": 9, "title": "Quadratische Funktionen", "explain": ["Bei y = ax² + bx + c mit a ≠ 0 entsteht eine Parabel. Ist a positiv, öffnet sie nach oben; ist a negativ, nach unten.", "Die Scheitelpunktform y = a(x − d)² + e zeigt den Scheitelpunkt S(d; e)."], "example": "y = (x − 2)² + 1 hat den Scheitelpunkt S(2; 1). Bei x = 2 ist y am kleinsten.", "tip": "In (x − d) steckt vor d ein Minus: (x + 2)² hat seinen Scheitel bei x = −2."}, {"id": "l27", "subject": "Mathe", "grade": 9, "title": "Lineare Gleichungssysteme", "explain": ["Ein Gleichungssystem sucht Werte, die mehrere Gleichungen gleichzeitig erfüllen.", "Beim Additionsverfahren addierst oder subtrahierst du Gleichungen so, dass eine Variable wegfällt."], "example": "x + y = 7 und x − y = 1. Addieren ergibt 2x = 8, also x = 4. Einsetzen ergibt y = 3.", "tip": "Prüfe die Lösung in beiden ursprünglichen Gleichungen."}, {"id": "l28", "subject": "Mathe", "grade": 10, "title": "Trigonometrie im rechtwinkligen Dreieck", "explain": ["Sinus, Kosinus und Tangens verknüpfen Seitenverhältnisse mit einem spitzen Winkel α.", "sin α = Gegenkathete/Hypotenuse; cos α = Ankathete/Hypotenuse; tan α = Gegenkathete/Ankathete."], "example": "Bei α = 30° und Hypotenuse 10 cm ist die Gegenkathete 10 · sin(30°) = 5 cm.", "tip": "Gegen- und Ankathete hängen vom gewählten Winkel ab. Stelle den Rechner für Gradangaben auf Gradmaß."}, {"id": "l29", "subject": "Mathe", "grade": 10, "title": "Exponentielles Wachstum", "explain": ["Beim exponentiellen Wachstum wird in gleichen Zeitabständen immer mit demselben Faktor multipliziert.", "Das Modell lautet N(t) = N₀ · qᵗ. Bei 5 % Zuwachs ist q = 1,05; bei 5 % Abnahme q = 0,95."], "example": "100 · 1,05² = 110,25. Nach zwei Schritten mit je 5 % Zuwachs sind es 110,25 statt 110.", "tip": "Prozentänderungen beziehen sich jeweils auf den neuen Zwischenwert."}, {"id": "l30", "subject": "Mathe", "grade": 10, "title": "Statistik kritisch lesen", "explain": ["Der Mittelwert ist die Summe aller Werte geteilt durch ihre Anzahl. Der Median ist der mittlere Wert der sortierten Liste; bei gerader Anzahl der Mittelwert der beiden mittleren.", "Ausreißer beeinflussen den Mittelwert oft stark. Für eine Bewertung brauchst du auch Streuung und Auswahl der Daten."], "example": "Bei 1, 2, 2, 3, 12 ist der Mittelwert 4, der Median 2. Beide beschreiben dieselben Daten unterschiedlich.", "tip": "Ein Zusammenhang zwischen zwei Größen beweist keine Ursache."}, {"id": "l31", "subject": "Deutsch", "grade": 1, "title": "Laute und Buchstaben", "explain": ["Laute hörst du. Buchstaben siehst und schreibst du. Mehrere Buchstaben können zusammen für einen Laut stehen.", "Sprich ein Wort langsam und höre auf seine Teile."], "example": "In „Schaf“ bilden s, c und h zusammen den Laut „sch“. Das Wort hat fünf Buchstaben und drei Laute.", "tip": "Buchstaben und Laute sind nicht immer gleich viele."}, {"id": "l32", "subject": "Deutsch", "grade": 1, "title": "Silben klatschen", "explain": ["Wörter lassen sich in Sprechstücke teilen. Diese heißen Silben.", "Sprich langsam und klatsche zu jedem Sprechstück einmal."], "example": "„Ha-se“ hat zwei Silben. „Ba-na-ne“ hat drei Silben.", "tip": "Sprich das Wort natürlich; die Klatschhilfe soll dich beim Hören unterstützen."}, {"id": "l33", "subject": "Deutsch", "grade": 1, "title": "Ein einfacher Satz", "explain": ["Ein Satz kann sagen, wer etwas tut und was passiert. Am Anfang schreibst du groß.", "Am Ende zeigt ein Satzzeichen, ob du etwas sagst, fragst oder ausrufst."], "example": "„Lina malt.“ ist eine Aussage. „Malt Lina?“ ist eine Frage.", "tip": "Lies deinen Satz laut: Versteht man, was du sagen möchtest?"}, {"id": "l34", "subject": "Deutsch", "grade": 2, "title": "Nomen erkennen", "explain": ["Nomen benennen zum Beispiel Menschen, Tiere, Dinge oder Gefühle. Du schreibst sie groß.", "Oft passt ein Begleiter wie der, die, das, ein oder eine davor."], "example": "der Hund, die Schule, das Glück. In „Der Hund schläft“ ist „Hund“ ein Nomen.", "tip": "Auch etwas, das du nicht anfassen kannst, kann ein Nomen sein: die Freude."}, {"id": "l35", "subject": "Deutsch", "grade": 2, "title": "Verben und Adjektive", "explain": ["Verben sagen oft, was jemand tut oder was geschieht. Adjektive beschreiben, wie etwas ist.", "Ein Verb verändert sich passend zur Person."], "example": "„Der kleine Hund rennt.“ „kleine“ beschreibt den Hund, „rennt“ sagt, was er tut. Ich renne, du rennst.", "tip": "Frage bei einem Adjektiv: Wie ist jemand oder etwas?"}, {"id": "l36", "subject": "Deutsch", "grade": 2, "title": "Punkt, Fragezeichen, Ausrufezeichen", "explain": ["Ein Punkt beendet meist eine Aussage. Ein Fragezeichen beendet eine direkte Frage.", "Ein Ausrufezeichen kann einen Ausruf oder eine nachdrückliche Aufforderung markieren."], "example": "„Es regnet.“ – „Regnet es?“ – „Pass auf!“", "tip": "Nicht jeder Satz braucht ein Ausrufezeichen. Wähle nach der Bedeutung."}, {"id": "l37", "subject": "Deutsch", "grade": 3, "title": "Vergangenheit erzählen", "explain": ["Verben können zeigen, wann etwas passiert. Das Präsens steht häufig für die Gegenwart.", "Beim Erzählen nutzt du auch Vergangenheit: Präteritum oder Perfekt."], "example": "Heute spiele ich. Gestern spielte ich. Gestern habe ich gespielt.", "tip": "Das Perfekt besteht oft aus „haben“ oder „sein“ und einer weiteren Verbform: ist gelaufen."}, {"id": "l38", "subject": "Deutsch", "grade": 3, "title": "Wörter verlängern", "explain": ["Manche Enden klingen anders, als sie geschrieben werden. Beim Verlängern kannst du den passenden Buchstaben besser hören.", "Bilde etwa die Mehrzahl oder eine längere Form."], "example": "„Hund“ klingt am Ende ähnlich wie „Hunt“. Bei „Hunde“ hörst du das d. „lieb“ – „liebe“.", "tip": "Verlängern hilft vor allem bei b/p, d/t und g/k am Wort- oder Silbenende."}, {"id": "l39", "subject": "Deutsch", "grade": 3, "title": "Geschichten aufbauen", "explain": ["Eine Geschichte hat oft einen Anfang, einen Hauptteil und einen Schluss.", "Am Anfang lernst du Personen und Ort kennen. Im Hauptteil passiert etwas. Der Schluss rundet die Geschichte ab."], "example": "Anfang: Mia findet einen Schlüssel. Hauptteil: Sie sucht die passende Tür. Schluss: Sie entdeckt eine alte Spielzeugkiste.", "tip": "Beschreibe auch, was die Figuren denken oder fühlen."}, {"id": "l40", "subject": "Deutsch", "grade": 4, "title": "Subjekt und Prädikat", "explain": ["Das Subjekt sagt, wer oder was etwas tut oder ist. Du findest es mit „Wer oder was?“.", "Das Prädikat enthält die Verbform oder Verbformen. Es sagt, was geschieht."], "example": "„Die Kinder haben im Garten gespielt.“ Wer? Die Kinder. Prädikat: haben gespielt.", "tip": "Ein Prädikat kann aus mehreren Teilen bestehen."}, {"id": "l41", "subject": "Deutsch", "grade": 4, "title": "Die vier Fälle", "explain": ["Nomen und ihre Begleiter können im Nominativ, Genitiv, Dativ oder Akkusativ stehen.", "Die Fragen helfen: Wer oder was? Wessen? Wem? Wen oder was?"], "example": "„Der Junge gibt dem Hund den Ball.“ Der Junge: Nominativ. Dem Hund: Dativ. Den Ball: Akkusativ. „Das Halsband des Hundes“: Genitiv.", "tip": "Frage immer im Zusammenhang des ganzen Satzes."}, {"id": "l42", "subject": "Deutsch", "grade": 4, "title": "Sachtexte verstehen", "explain": ["Ein Sachtext erklärt oder informiert. Lies zuerst die Überschrift und betrachte Bilder.", "Lies dann Abschnitt für Abschnitt. Suche die Hauptaussage und kläre unbekannte Wörter."], "example": "Bei einem Text über Bienen kannst du notieren: Nahrung, Lebensraum und Aufgaben im Bienenvolk.", "tip": "Eine kurze Zusammenfassung enthält die wichtigsten Informationen in eigenen Worten."}, {"id": "l43", "subject": "Deutsch", "grade": 5, "title": "Wortarten unterscheiden", "explain": ["Nomen, Verben und Adjektive sind Wortarten. Dazu kommen unter anderem Artikel, Pronomen und Präpositionen.", "Pronomen können Nomen begleiten oder ersetzen. Präpositionen beschreiben Beziehungen, etwa räumlich oder zeitlich."], "example": "„Sie legt das rote Buch auf den Tisch.“ Sie: Pronomen; legt: Verb; das: Artikel; rote: Adjektiv; Buch: Nomen; auf: Präposition.", "tip": "Wortart und Satzglied sind verschiedene Dinge: Ein Satzglied kann mehrere Wörter enthalten."}, {"id": "l44", "subject": "Deutsch", "grade": 5, "title": "Eine gute Beschreibung", "explain": ["Eine Beschreibung stellt etwas genau und geordnet dar. Du nutzt treffende Wörter und meist das Präsens.", "Gehe zum Beispiel vom Gesamteindruck zu einzelnen Merkmalen. Trenne Beobachtung und Vermutung."], "example": "„Der Rucksack ist blau, hat zwei Seitentaschen und einen gelben Reißverschluss.“ Das ist genauer als „Er sieht cool aus“.", "tip": "Beschreibe so, dass jemand ohne Bild eine klare Vorstellung bekommt."}, {"id": "l45", "subject": "Deutsch", "grade": 5, "title": "Wörtliche Rede", "explain": ["Wörtliche Rede gibt die gesprochenen Worte direkt wieder. Sie steht in Anführungszeichen.", "Der Begleitsatz nennt oft, wer spricht. Seine Position beeinflusst die Zeichensetzung."], "example": "Mia sagt: „Ich komme.“ – „Ich komme“, sagt Mia. – „Kommst du?“, fragt Mia.", "tip": "Frage- und Ausrufezeichen bleiben innerhalb der Anführungszeichen."}, {"id": "l46", "subject": "Deutsch", "grade": 6, "title": "Hauptsatz und Nebensatz", "explain": ["Ein Hauptsatz kann als selbstständiger Satz stehen. In einem Aussagesatz steht das finite Verb meist an zweiter Stelle.", "In einem mit „weil“ oder „dass“ eingeleiteten Nebensatz steht das finite Verb am Ende. Haupt- und Nebensatz werden durch ein Komma getrennt."], "example": "„Ich bleibe zu Hause, weil ich krank bin.“ Hauptsatz: Ich bleibe zu Hause. Nebensatz: weil ich krank bin.", "tip": "Das finite Verb ist die Verbform, die zur Person passt: ich bin, du bist."}, {"id": "l47", "subject": "Deutsch", "grade": 6, "title": "Eine Inhaltsangabe schreiben", "explain": ["Eine Inhaltsangabe fasst die Handlung sachlich und knapp zusammen. Schreibe überwiegend im Präsens und in eigenen Worten.", "Nenne im Einleitungssatz, soweit bekannt, Titel, Autor, Textart und Thema. Beschränke den Hauptteil auf die wesentlichen Ereignisse."], "example": "Aus „Dann rannte er ganz, ganz schnell davon!“ kann werden: „Die Hauptfigur flieht.“", "tip": "Eine Inhaltsangabe enthält normalerweise keine eigene Bewertung und keine nacherzählten Dialoge."}, {"id": "l48", "subject": "Deutsch", "grade": 6, "title": "Gedichte entdecken", "explain": ["Gedichte bestehen oft aus Versen und Strophen. Ein Vers ist eine Zeile, eine Strophe eine Gruppe von Versen.", "Reime, Rhythmus und sprachliche Bilder können eine Wirkung erzeugen. Nicht jedes Gedicht reimt sich."], "example": "Reimen sich Zeile 1 und 2 sowie 3 und 4, heißt das Paarreim: aabb.", "tip": "Beschreibe nicht nur ein Merkmal, sondern auch seine mögliche Wirkung."}, {"id": "l49", "subject": "Deutsch", "grade": 7, "title": "Argumente aufbauen", "explain": ["Ein Argument begründet eine Behauptung. Ein Beispiel macht die Begründung anschaulich.", "Unterscheide Behauptung, Begründung und Beispiel. Ein einzelnes Beispiel beweist noch keine allgemeine Regel."], "example": "Behauptung: Mehr Schatten auf dem Schulhof ist sinnvoll. Begründung: Schatten bietet bei Sonne kühlere Aufenthaltsorte. Beispiel: Sitzplätze unter Bäumen.", "tip": "Gute Argumente sind nachvollziehbar und beziehen sich auf die Streitfrage."}, {"id": "l50", "subject": "Deutsch", "grade": 7, "title": "Aktiv und Passiv", "explain": ["Im Aktiv steht meist die handelnde Person im Mittelpunkt. Das Vorgangspassiv betont, was mit jemandem oder etwas geschieht.", "Es wird mit einer Form von „werden“ und dem Partizip II gebildet."], "example": "Aktiv: „Die Klasse gestaltet das Plakat.“ Passiv: „Das Plakat wird von der Klasse gestaltet.“", "tip": "Passiv kann die handelnde Person weglassen. Prüfe, ob dadurch eine wichtige Information fehlt."}, {"id": "l51", "subject": "Deutsch", "grade": 7, "title": "Balladen verstehen", "explain": ["Eine Ballade ist ein erzählendes Gedicht. Sie verbindet häufig Handlung, lyrische Gestaltung und szenische oder dialogische Elemente.", "Untersuche Handlung, Figuren, Aufbau und Sprache zusammen."], "example": "Ein Dialog kann einen Konflikt unmittelbar zeigen. Kurze Verse können in einer bestimmten Passage Tempo erzeugen.", "tip": "Belege deine Deutung mit passenden Textstellen; eine Wirkung ist nicht automatisch immer gleich."}, {"id": "l52", "subject": "Deutsch", "grade": 8, "title": "Konjunktiv und indirekte Rede", "explain": ["Indirekte Rede gibt Aussagen sinngemäß wieder. In sachlichen Texten kennzeichnet oft der Konjunktiv I die Wiedergabe.", "Ist die Form nicht vom Indikativ unterscheidbar, kann eine Ersatzform im Konjunktiv II helfen."], "example": "Direkt: „Ich bin müde.“ Indirekt: Sie sagt, sie sei müde.", "tip": "Der Konjunktiv I zeigt die Wiedergabe einer Aussage; er bedeutet nicht automatisch, dass sie falsch ist."}, {"id": "l53", "subject": "Deutsch", "grade": 8, "title": "Kurzgeschichten untersuchen", "explain": ["Kurzgeschichten beginnen oft unmittelbar und lassen manches offen. Alltagssituationen können einen Wendepunkt sichtbar machen.", "Achte auf Erzählperspektive, Verhalten, Konflikte und sprachliche Hinweise."], "example": "Wenn eine Figur auf eine Frage schweigt, können verschiedene Deutungen möglich sein. Prüfe, welche der Text stützt.", "tip": "Nicht jedes typische Merkmal kommt in jeder Kurzgeschichte vor."}, {"id": "l54", "subject": "Deutsch", "grade": 8, "title": "Sachlich erörtern", "explain": ["Eine Erörterung untersucht eine Frage mit Argumenten. Du ordnest Begründungen, prüfst Gegenargumente und kommst zu einem begründeten Urteil.", "Ein klarer Absatz behandelt jeweils einen wesentlichen Gedanken."], "example": "Bei einer Handyregelung kannst du Ablenkung, Erreichbarkeit und Unterrichtsnutzung gegeneinander abwägen.", "tip": "Ein Gegenargument fair darzustellen macht die eigene Begründung stärker."}, {"id": "l55", "subject": "Deutsch", "grade": 9, "title": "Literarische Texte interpretieren", "explain": ["Eine Interpretation verbindet Beobachtung und Deutung. Du erklärst, wie Inhalt, Form und Sprache zusammenwirken.", "Formuliere eine Deutungshypothese, prüfe sie am Text und passe sie bei Bedarf an."], "example": "Beobachtung: Eine Figur spricht nur in kurzen Sätzen. Mögliche Deutung: Unsicherheit. Prüfe Situation und weitere Hinweise, bevor du das behauptest.", "tip": "Eine Deutung braucht Textbelege und eine nachvollziehbare Verbindung zur Aussage."}, {"id": "l56", "subject": "Deutsch", "grade": 9, "title": "Rhetorische Mittel", "explain": ["Rhetorische Mittel gestalten Sprache gezielt. Eine Metapher überträgt Bedeutung; ein Vergleich verknüpft mit „wie“ oder „als“.", "Eine rhetorische Frage erwartet keine echte Antwort. Die Wirkung hängt immer vom Kontext ab."], "example": "„Ein Meer aus Lichtern“ ist eine Metapher. „Die Lichter funkeln wie Sterne“ ist ein Vergleich.", "tip": "Das Benennen allein reicht nicht: Erkläre, was das Mittel an dieser Stelle bewirkt."}, {"id": "l57", "subject": "Deutsch", "grade": 9, "title": "Materialgestützt schreiben", "explain": ["Beim materialgestützten Schreiben nutzt du Informationen aus mehreren vorgegebenen Quellen für eine eigene Textaufgabe.", "Prüfe Auftrag, Zielgruppe, Quellenlage und Widersprüche. Ordne Informationen nach Themen, nicht bloß nach Quellen."], "example": "Für einen Informationstext über Schulwege kannst du eine Karte, eine Befragung und einen Sachtext sinnvoll verbinden.", "tip": "Trenne eigene Schlussfolgerungen von belegten Angaben und kennzeichne Übernahmen."}, {"id": "l58", "subject": "Deutsch", "grade": 10, "title": "Eine Textanalyse strukturieren", "explain": ["Eine Analyse untersucht systematisch, wie ein Text gestaltet ist und welche Funktion das hat.", "Einleitung: Textdaten und Thema. Hauptteil: geordnete Analyse mit Belegen. Schluss: Ergebnisse bezogen auf die Fragestellung."], "example": "Bei einem Kommentar untersuchst du These, Argumentationsgang, Sprache und beabsichtigte Wirkung auf die Zielgruppe.", "tip": "Vermeide eine bloße Nacherzählung: Jede Beobachtung sollte zur Analyse beitragen."}, {"id": "l59", "subject": "Deutsch", "grade": 10, "title": "Sprache und Manipulation", "explain": ["Sprache kann Perspektiven hervorheben und andere ausblenden. Wertende Begriffe, Auslassungen und unklare Verallgemeinerungen können die Wahrnehmung beeinflussen.", "Prüfe, welche Informationen belegt sind und welche Deutung nahegelegt wird."], "example": "„Alle wissen doch …“ ersetzt keinen Beleg. Frage: Wer genau? Welche Daten? Welche Gegenbeispiele?", "tip": "Eine emotionale Formulierung ist nicht automatisch falsch; prüfe ihre Aussage und Begründung."}, {"id": "l60", "subject": "Deutsch", "grade": 10, "title": "Überarbeiten und Prüfungstexte planen", "explain": ["Planung hilft, einen Text auf die Aufgabe auszurichten. Markiere Operatoren wie „analysieren“, „erläutern“ oder „beurteilen“.", "Erstelle eine Gliederung. Überarbeite erst Inhalt und Aufbau, dann Ausdruck, Grammatik und Rechtschreibung."], "example": "Bei „beurteilen“ brauchst du Kriterien und ein begründetes Urteil. Eine reine Zusammenfassung erfüllt den Auftrag nicht.", "tip": "Reserviere bewusst Zeit für die Schlusskontrolle."}, {"id": "l61", "subject": "Englisch", "grade": 1, "title": "Hello! Sich begrüßen", "explain": ["„Hello“ heißt „Hallo“. Mit „Goodbye“ verabschiedest du dich.", "Wenn du deinen Namen sagst, kannst du „My name is …“ verwenden."], "example": "Hello! My name is Mia. → Hallo! Ich heiße Mia.", "tip": "Sprich kurze Sätze laut. Du musst am Anfang nicht jedes Wort schreiben können."}, {"id": "l62", "subject": "Englisch", "grade": 1, "title": "Farben entdecken", "explain": ["Farben helfen dir, Dinge zu beschreiben: red = rot, blue = blau, green = grün, yellow = gelb.", "Im Englischen steht die Farbe meist vor dem Ding."], "example": "a red ball → ein roter Ball. a blue bag → eine blaue Tasche.", "tip": "Verbinde jedes neue Wort mit einem Gegenstand oder einer Farbe."}, {"id": "l63", "subject": "Englisch", "grade": 1, "title": "Zahlen von eins bis zehn", "explain": ["Die ersten Zahlen heißen one, two, three, four, five, six, seven, eight, nine, ten.", "Zähle echte Dinge und sage das englische Wort dazu."], "example": "one apple → ein Apfel; two apples → zwei Äpfel.", "tip": "Bei mehreren Dingen bekommt das englische Nomen oft ein s."}, {"id": "l64", "subject": "Englisch", "grade": 2, "title": "Meine Familie", "explain": ["„Family“ bedeutet Familie. „Mother“ heißt Mutter, „father“ Vater, „sister“ Schwester und „brother“ Bruder.", "Mit „This is …“ stellst du jemanden vor."], "example": "This is my sister. → Das ist meine Schwester.", "tip": "Familien sind unterschiedlich. Übe mit den Personen, die zu deiner Familie gehören."}, {"id": "l65", "subject": "Englisch", "grade": 2, "title": "Tiere und Mehrzahl", "explain": ["„Cat“ heißt Katze, „dog“ Hund, „bird“ Vogel. Für mehrere Tiere hängst du oft ein s an.", "Es gibt auch besondere Mehrzahlformen; die lernst du nach und nach."], "example": "one dog – two dogs. Aber: one mouse – two mice.", "tip": "Die Mehrzahl endet oft auf s, aber nicht immer."}, {"id": "l66", "subject": "Englisch", "grade": 2, "title": "I like: Was ich mag", "explain": ["Mit „I like …“ sagst du, was du magst. „I don't like …“ heißt: Ich mag … nicht.", "Du kannst über Essen, Tiere oder Aktivitäten sprechen."], "example": "I like apples. → Ich mag Äpfel. I don't like milk. → Ich mag keine Milch.", "tip": "Lerne kurze ganze Sätze, die du im Alltag benutzen kannst."}, {"id": "l67", "subject": "Englisch", "grade": 3, "title": "Schulsachen benennen", "explain": ["„Book“ heißt Buch, „pencil“ Bleistift, „ruler“ Lineal und „schoolbag“ Schultasche.", "„A“ bedeutet ein oder eine. Vor einem Vokallaut steht „an“."], "example": "a book, a pencil, an apple.", "tip": "Entscheidend ist der Laut am Wortanfang, nicht nur der geschriebene Buchstabe."}, {"id": "l68", "subject": "Englisch", "grade": 3, "title": "I am, you are", "explain": ["Das Verb „be“ heißt sein. Seine Form hängt davon ab, über wen du sprichst.", "I am, you are, he/she/it is, we are, you are, they are."], "example": "I am happy. → Ich bin glücklich. She is happy. → Sie ist glücklich.", "tip": "„I'm“ ist die Kurzform von „I am“, „you're“ von „you are“."}, {"id": "l69", "subject": "Englisch", "grade": 3, "title": "Wo ist etwas?", "explain": ["„In“ bedeutet in, „on“ auf und „under“ unter. Diese Wörter beschreiben, wo sich etwas befindet.", "Du kannst einen Gegenstand hinlegen und seinen Ort beschreiben."], "example": "The ball is under the table. → Der Ball ist unter dem Tisch.", "tip": "Merke dir Ortswörter mit kleinen Bildern oder echten Gegenständen."}, {"id": "l70", "subject": "Englisch", "grade": 4, "title": "Simple present: Gewohnheiten", "explain": ["Das simple present nutzt du unter anderem für Gewohnheiten und allgemeine Tatsachen.", "Bei he, she und it bekommt das Verb normalerweise ein s. Manche Wörter ändern ihre Schreibweise."], "example": "I play football. She plays football. He watches TV.", "tip": "He, she, it: Das s gehört meist mit."}, {"id": "l71", "subject": "Englisch", "grade": 4, "title": "Fragen mit do und does", "explain": ["Bei vielen Verben bildest du Fragen im simple present mit do oder does.", "Für he, she und it verwendest du does. Das Hauptverb steht dann in der Grundform."], "example": "Do you like music? Does she like music?", "tip": "Nach does bekommt das Hauptverb kein zusätzliches s."}, {"id": "l72", "subject": "Englisch", "grade": 4, "title": "Die Uhrzeit sagen", "explain": ["Mit „What time is it?“ fragst du nach der Uhrzeit. Ganze Stunden kannst du mit „o'clock“ sagen.", "„Half past“ heißt eine halbe Stunde nach der genannten Stunde."], "example": "It's three o'clock. → Es ist drei Uhr. It's half past three. → Es ist halb vier.", "tip": "Englisches „half past three“ bedeutet 3:30, nicht 2:30."}, {"id": "l73", "subject": "Englisch", "grade": 5, "title": "Verneinung im simple present", "explain": ["Bei den meisten Verben nutzt du don't oder doesn't. Danach folgt die Grundform des Verbs.", "Bei be brauchst du kein do: I am not, she isn't, they aren't."], "example": "He doesn't play tennis. Aber: He isn't tired.", "tip": "„He doesn't plays“ ist falsch: Das s steckt bereits in does."}, {"id": "l74", "subject": "Englisch", "grade": 5, "title": "Possessivbegleiter: my und your", "explain": ["Possessivbegleiter zeigen eine Zugehörigkeit: my, your, his, her, its, our, your, their.", "Sie stehen vor einem Nomen und richten sich nach der Person oder Sache, zu der etwas gehört."], "example": "This is her bike. → Das ist ihr Fahrrad. This is our classroom. → Das ist unser Klassenraum.", "tip": "„Its“ zeigt Zugehörigkeit; „it's“ ist kurz für „it is“ oder „it has“."}, {"id": "l75", "subject": "Englisch", "grade": 5, "title": "Wortstellung im Aussagesatz", "explain": ["Ein einfacher englischer Aussagesatz folgt häufig der Reihenfolge Subjekt – Verb – Objekt.", "Orts- und Zeitangaben folgen oft danach. Im Englischen lässt sich die Wortstellung weniger frei verändern als im Deutschen."], "example": "Mia reads a book at home in the evening.", "tip": "Übersetze nicht jedes deutsche Wort an derselben Stelle."}, {"id": "l76", "subject": "Englisch", "grade": 6, "title": "Simple past", "explain": ["Das simple past beschreibt abgeschlossene Ereignisse in der Vergangenheit. Regelmäßige Verben erhalten meist -ed.", "Unregelmäßige Formen wie go → went lernst du mit. Fragen und Verneinungen nutzen did und die Grundform."], "example": "Yesterday I played. She went home. Did she go home? She didn't go home.", "tip": "Nach did oder didn't steht die Grundform, nicht die Vergangenheitsform."}, {"id": "l77", "subject": "Englisch", "grade": 6, "title": "Present progressive", "explain": ["Das present progressive beschreibt oft, was gerade passiert. Es besteht aus am/is/are und der Verbform mit -ing.", "Es kann auch vorübergehende Situationen ausdrücken."], "example": "I am reading now. She is playing outside. Im Gegensatz: She plays every day.", "tip": "Vergleiche „gerade jetzt“ mit einer Gewohnheit."}, {"id": "l78", "subject": "Englisch", "grade": 6, "title": "Adjektive steigern", "explain": ["Kurze Adjektive werden häufig mit -er und -est gesteigert. Längere nutzen meist more und most.", "Einige Formen sind unregelmäßig: good – better – best."], "example": "small – smaller – the smallest. interesting – more interesting – the most interesting.", "tip": "Für Vergleiche steht „than“: This bag is smaller than that one."}, {"id": "l79", "subject": "Englisch", "grade": 7, "title": "Present perfect", "explain": ["Das present perfect verbindet Vergangenheit und Gegenwart. Es besteht aus have/has und dem past participle.", "Du nutzt es etwa für Erfahrungen bis jetzt oder Ergebnisse mit Gegenwartsbezug. Für einen abgeschlossenen Zeitpunkt passt oft simple past."], "example": "I have lost my key. → Der Schlüssel fehlt jetzt. I lost it yesterday. → Das Ereignis wird zeitlich eingeordnet.", "tip": "have/has + dritte Verbform: see – saw – seen."}, {"id": "l80", "subject": "Englisch", "grade": 7, "title": "Will und going to", "explain": ["„Going to“ wird häufig für bestehende Absichten oder Vorhersagen aufgrund sichtbarer Anzeichen verwendet.", "„Will“ kann spontane Entscheidungen, Versprechen oder Vorhersagen ausdrücken. Der Kontext entscheidet."], "example": "Look at those clouds. It's going to rain. – I'll help you with your bag.", "tip": "Beide Formen reden über die Zukunft, setzen aber oft unterschiedliche Schwerpunkte."}, {"id": "l81", "subject": "Englisch", "grade": 7, "title": "Modalverben", "explain": ["Modalverben wie can, must und should verändern die Aussage eines anderen Verbs.", "Danach folgt die Grundform ohne to. Sie bekommen bei he, she und it kein s."], "example": "She can swim. You should rest. You mustn't touch it. → Du darfst es nicht berühren.", "tip": "mustn't heißt „nicht dürfen“; don't have to heißt „nicht müssen“."}, {"id": "l82", "subject": "Englisch", "grade": 8, "title": "If-Sätze: Typ 1 und 2", "explain": ["Typ 1 beschreibt eine als möglich betrachtete Bedingung: if + simple present, oft will im Hauptsatz.", "Typ 2 beschreibt eine hypothetische oder weniger wahrscheinliche Situation: if + simple past, would + Grundform."], "example": "If it rains, we will stay home. If I had wings, I would fly.", "tip": "Die Vergangenheitsform in Typ 2 meint hier nicht automatisch Vergangenheit."}, {"id": "l83", "subject": "Englisch", "grade": 8, "title": "Passiv im Englischen", "explain": ["Das Passiv lenkt den Blick auf den Vorgang oder die betroffene Sache.", "Es wird mit einer passenden Form von be und dem past participle gebildet."], "example": "They clean the room. → The room is cleaned. They cleaned it. → It was cleaned.", "tip": "Die Zeitform steckt in be; das past participle bleibt gleich."}, {"id": "l84", "subject": "Englisch", "grade": 8, "title": "Relativsätze", "explain": ["Relativsätze beschreiben ein Nomen genauer. Who bezieht sich auf Personen, which auf Dinge; that ist in vielen notwendigen Relativsätzen möglich.", "Zusätzliche Informationen werden durch Kommas abgetrennt. In solchen Sätzen verwendest du kein that."], "example": "The girl who lives next door is my friend. My bike, which is red, is outside.", "tip": "Kommas können die Bedeutung verändern: notwendig eingrenzen oder nur ergänzen?"}, {"id": "l85", "subject": "Englisch", "grade": 9, "title": "Past perfect", "explain": ["Das past perfect zeigt, dass etwas vor einem anderen Zeitpunkt in der Vergangenheit passiert war.", "Du bildest es mit had und dem past participle."], "example": "When I arrived, the bus had left. → Als ich ankam, war der Bus schon abgefahren.", "tip": "Ordne die Ereignisse: erst Abfahrt, dann Ankunft."}, {"id": "l86", "subject": "Englisch", "grade": 9, "title": "Reported speech", "explain": ["Reported speech gibt Aussagen indirekt wieder. Nach einem Einleitungsverb in der Vergangenheit werden Zeitformen häufig zurückverschoben.", "Pronomen und Zeitangaben passen sich der Perspektive an. Bei weiterhin gültigen Aussagen ist eine Rückverschiebung nicht immer nötig."], "example": "She said, “I am tired.” → She said that she was tired.", "tip": "Überlege, wer wann über wen spricht, statt Wörter mechanisch zu ersetzen."}, {"id": "l87", "subject": "Englisch", "grade": 9, "title": "Einen comment schreiben", "explain": ["Ein comment stellt eine begründete eigene Position dar. Einleitung, geordnete Argumente und Schluss machen sie nachvollziehbar.", "Verbinde Behauptung, Erklärung und Beispiel. Beziehe eine Gegenposition fair ein."], "example": "In my view … / One reason is … / For example … / However … / Therefore …", "tip": "Viele Verbindungswörter ersetzen keine klaren Gedanken."}, {"id": "l88", "subject": "Englisch", "grade": 10, "title": "If-Sätze: Typ 3", "explain": ["Typ 3 beschreibt eine nicht eingetretene Möglichkeit in der Vergangenheit.", "Die Grundform lautet: if + past perfect, would have + past participle."], "example": "If I had left earlier, I would have caught the bus. → Wäre ich früher losgegangen, hätte ich den Bus erreicht.", "tip": "Der Satz blickt auf eine Vergangenheit zurück, die sich nicht mehr ändern lässt."}, {"id": "l89", "subject": "Englisch", "grade": 10, "title": "Mediation: Sinngemäß vermitteln", "explain": ["Bei mediation überträgst du die relevanten Informationen für eine bestimmte Person und Situation.", "Du übersetzt nicht Wort für Wort. Wähle aus, erkläre kulturelle Begriffe und passe die Sprache an die Zielgruppe an."], "example": "Ein englischsprachiger Gast braucht aus einem langen deutschen Aushang vielleicht nur Öffnungszeiten, Ort und Anmeldung.", "tip": "Keine wichtigen Informationen erfinden oder weglassen; der konkrete Auftrag bestimmt die Auswahl."}, {"id": "l90", "subject": "Englisch", "grade": 10, "title": "Texte analysieren und belegen", "explain": ["Eine englische analysis erklärt, wie ein Text seine Wirkung erzeugt. Untersuche etwa structure, language, tone und narrative perspective.", "Verknüpfe deine Aussage mit einem kurzen Beleg und einer Erklärung."], "example": "The repeated phrase emphasises … This suggests … The contrast highlights …", "tip": "Verwende present tense für die Textanalyse und prüfe Zitate am Original."}, {"id": "l91", "subject": "Politik", "grade": 1, "title": "Warum gibt es Regeln?", "explain": ["Regeln helfen, damit wir gut miteinander leben können. Sie können Menschen schützen und Streit vermeiden.", "Eine gute Regel hat einen verständlichen Grund. Über Regeln darf man gemeinsam nachdenken."], "example": "In der Klasse sprechen wir nacheinander. So kann jedes Kind gehört werden.", "tip": "Frage: Wem hilft die Regel, und warum brauchen wir sie?"}, {"id": "l92", "subject": "Politik", "grade": 1, "title": "Wünsche und Bedürfnisse", "explain": ["Ein Wunsch ist etwas, das du gerne hättest. Ein Bedürfnis ist etwas, das du für dein Leben und Wohlbefinden brauchst.", "Essen, Schutz und Zuwendung sind grundlegende Bedürfnisse."], "example": "Du brauchst etwas zu trinken. Eine bestimmte bunte Trinkflasche zu bekommen ist ein Wunsch.", "tip": "Nicht jeder Wunsch muss erfüllt werden; Bedürfnisse verdienen Aufmerksamkeit."}, {"id": "l93", "subject": "Politik", "grade": 1, "title": "Streit friedlich lösen", "explain": ["Bei einem Streit wollen Menschen oft verschiedene Dinge. Du darfst sagen, was dich ärgert, ohne jemanden zu verletzen.", "Höre zu, beschreibe dein Gefühl und sucht eine Lösung. Wenn du Angst hast, hole Hilfe."], "example": "„Ich bin traurig, weil ich auch mitspielen möchte. Können wir uns abwechseln?“", "tip": "Hilfe zu holen ist kein Petzen, wenn jemand verletzt oder bedroht wird."}, {"id": "l94", "subject": "Politik", "grade": 2, "title": "Gemeinsam entscheiden", "explain": ["Manchmal kann eine Gruppe gemeinsam auswählen. Zuerst sollten alle verstehen, worum es geht.", "Dann hören die Beteiligten einander zu und entscheiden nach einer vereinbarten Regel."], "example": "Die Klasse sammelt zwei Ausflugsziele, bespricht Vor- und Nachteile und stimmt ab.", "tip": "Eine Abstimmung braucht eine klare Frage."}, {"id": "l95", "subject": "Politik", "grade": 2, "title": "Fair ist nicht immer gleich", "explain": ["Gerechtigkeit kann bedeuten, dass alle dieselbe Chance bekommen. Dafür brauchen Menschen manchmal unterschiedliche Unterstützung.", "Gleiche Behandlung hilft nicht in jeder Situation gleich gut."], "example": "Ein Kind braucht beim Lesen größere Schrift. Diese Hilfe ermöglicht ihm, besser mitzumachen.", "tip": "Frage nicht nur „Bekommen alle dasselbe?“, sondern „Können alle mitmachen?“."}, {"id": "l96", "subject": "Politik", "grade": 2, "title": "Aufgaben in der Gemeinschaft", "explain": ["In einer Gemeinschaft übernehmen Menschen Aufgaben füreinander. Manche Aufgaben werden freiwillig, andere beruflich erledigt.", "Gemeinsame Arbeit gelingt besser, wenn Zuständigkeiten klar sind."], "example": "In der Schule kümmern sich verschiedene Menschen um Unterricht, Reinigung, Essen und Reparaturen.", "tip": "Auch wenig sichtbare Arbeit ist wichtig."}, {"id": "l97", "subject": "Politik", "grade": 3, "title": "Kinderrechte verstehen", "explain": ["Kinder haben eigene Rechte. Dazu gehören unter anderem Schutz, Bildung und Beteiligung.", "Mitbestimmen bedeutet, dass die Meinung von Kindern gehört und entsprechend ihrem Alter und ihrer Reife berücksichtigt wird."], "example": "Bei einer Entscheidung über den Schulhof sollen Kinder ihre Wünsche und Erfahrungen einbringen können.", "tip": "Ein Recht ist mehr als eine Belohnung für gutes Verhalten."}, {"id": "l98", "subject": "Politik", "grade": 3, "title": "Was macht eine Gemeinde?", "explain": ["Eine Gemeinde ist der Ort, in dem Menschen gemeinsam örtliche Angelegenheiten regeln.", "Dazu gehören je nach Zuständigkeit etwa Spielplätze, Straßen, Schulen oder Abfallentsorgung."], "example": "Wenn ein Spielplatz erneuert werden soll, müssen Bedarf, Geld und verschiedene Wünsche besprochen werden.", "tip": "Nicht jede Aufgabe vor Ort liegt bei derselben Stelle."}, {"id": "l99", "subject": "Politik", "grade": 3, "title": "Mehrheit und Minderheit", "explain": ["Bei einer Mehrheitsentscheidung setzt sich die Option mit der nötigen Stimmenzahl durch.", "Menschen, die anders abgestimmt haben, gehören zur Minderheit. Sie dürfen ihre Meinung weiterhin sagen und behalten ihre Rechte."], "example": "18 Kinder stimmen für Ziel A, 10 für Ziel B. A gewinnt diese Abstimmung. Die 10 Kinder dürfen trotzdem mitreden.", "tip": "Eine Mehrheit darf nicht einfach alle Rechte anderer außer Kraft setzen."}, {"id": "l100", "subject": "Politik", "grade": 4, "title": "Eine Wahl verstehen", "explain": ["Bei einer Wahl entscheiden Menschen, wer sie vertreten soll. Vorher sollten sie die Kandidierenden und deren Ideen kennenlernen.", "Die Wahl braucht faire Regeln. Eine geheime Abstimmung kann vor Druck schützen."], "example": "Bei der Klassensprecherwahl stellen Kinder ihre Ideen vor. Danach wird nach den vereinbarten Regeln gewählt.", "tip": "Ein schönes Versprechen sagt noch nicht, ob jemand es umsetzen kann."}, {"id": "l101", "subject": "Politik", "grade": 4, "title": "Nachrichten prüfen", "explain": ["Nachrichten berichten über Ereignisse. Nicht jede Behauptung im Internet ist eine verlässliche Nachricht.", "Prüfe: Wer hat es veröffentlicht? Wann? Welche Belege gibt es? Berichten andere verlässliche Quellen darüber?"], "example": "Ein altes Foto kann echt sein und trotzdem fälschlich als Bild von heute verbreitet werden.", "tip": "Bevor du etwas weiterleitest, prüfe den Zusammenhang."}, {"id": "l102", "subject": "Politik", "grade": 4, "title": "Öffentliche Aufgaben und Geld", "explain": ["Manche Angebote werden gemeinsam finanziert, zum Beispiel viele Straßen oder öffentliche Schulen.", "Öffentliche Einnahmen stammen unter anderem aus Steuern. Das Geld ist begrenzt und seine Verwendung muss entschieden werden."], "example": "Eine Gemeinde möchte eine Bücherei erneuern und einen Spielplatz bauen. Sie muss Kosten und Bedürfnisse abwägen.", "tip": "Öffentlich finanziert heißt nicht kostenlos hergestellt."}, {"id": "l103", "subject": "Politik", "grade": 5, "title": "Demokratie verstehen", "explain": ["In einer Demokratie geht politische Macht vom Volk aus. Beteiligung erfolgt unter anderem durch Wahlen und öffentliche Diskussion.", "Zu einer Demokratie gehören auch Grundrechte, Rechtsstaatlichkeit und Möglichkeiten, Macht zu kontrollieren."], "example": "Eine Regierung kann gewählt sein und muss sich trotzdem an geltendes Recht und geschützte Rechte halten.", "tip": "Demokratie ist mehr als nur die Entscheidung der Mehrheit."}, {"id": "l104", "subject": "Politik", "grade": 5, "title": "Meinung, Tatsache, Behauptung", "explain": ["Eine Tatsachenbehauptung lässt sich grundsätzlich überprüfen. Eine Meinung enthält eine Bewertung oder persönliche Einschätzung.", "Eine Aussage kann überprüfbare und wertende Teile gleichzeitig enthalten."], "example": "„Der Bus kam um 8:10 Uhr“ ist überprüfbar. „Die Fahrt war schön“ ist eine Bewertung.", "tip": "Auch eine Meinung kann mit zutreffenden oder unzutreffenden Angaben begründet werden."}, {"id": "l105", "subject": "Politik", "grade": 5, "title": "Konflikte und Kompromisse", "explain": ["In politischen Konflikten treffen unterschiedliche Interessen aufeinander. Ein Kompromiss versucht, eine gemeinsam tragbare Lösung zu finden.", "Beschreibe erst Interessen, dann mögliche Lösungen und ihre Folgen."], "example": "Ein Schulhof soll Raum für Ballspiele und Ruhe bieten. Getrennte Bereiche können beiden Bedürfnissen entgegenkommen.", "tip": "Ein Kompromiss ist nicht immer möglich oder fair. Prüfe, wer welche Nachteile trägt."}, {"id": "l106", "subject": "Politik", "grade": 6, "title": "Staat, Länder und Gemeinden", "explain": ["Deutschland ist föderal organisiert. Bund, Länder und Gemeinden übernehmen unterschiedliche Aufgaben und arbeiten zusammen.", "Welche Ebene zuständig ist, hängt vom Thema und der rechtlichen Aufgabenverteilung ab."], "example": "Schulpolitik ist in Deutschland überwiegend Sache der Länder. Gemeinden sind oft als Schulträger für Gebäude zuständig.", "tip": "„Der Staat“ ist keine einzelne Person oder Behörde."}, {"id": "l107", "subject": "Politik", "grade": 6, "title": "Gewaltenteilung", "explain": ["Staatliche Macht wird auf unterschiedliche Bereiche verteilt: Gesetzgebung, ausführende Gewalt und Rechtsprechung.", "Diese Bereiche sollen Macht begrenzen und kontrollieren. In der Praxis sind sie teilweise miteinander verflochten."], "example": "Ein Parlament beschließt Gesetze, Behörden wenden sie an und Gerichte entscheiden Rechtsstreitigkeiten.", "tip": "Gewalt bedeutet hier staatliche Macht, nicht körperliche Gewalt."}, {"id": "l108", "subject": "Politik", "grade": 6, "title": "Medien und Öffentlichkeit", "explain": ["Medien informieren, ordnen ein und können Macht kontrollieren. Sie wählen Themen und Perspektiven aus.", "Unterscheide Nachricht, Kommentar und Werbung. Achte auch darauf, wer einen Beitrag bezahlt."], "example": "Ein Bericht schildert eine Debatte; ein Kommentar bewertet sie. Ein bezahlter Beitrag hat zusätzlich ein Werbeinteresse.", "tip": "Eine Quelle zu prüfen bedeutet nicht, alle Quellen pauschal für unglaubwürdig zu halten."}, {"id": "l109", "subject": "Politik", "grade": 7, "title": "Parlament und Regierung", "explain": ["Ein Parlament berät und beschließt Gesetze und kontrolliert die Regierung. Eine Regierung führt politische Aufgaben im Rahmen ihrer Befugnisse aus.", "In parlamentarischen Demokratien hängt die Regierung von parlamentarischer Unterstützung ab."], "example": "Abgeordnete können der Regierung Fragen stellen und ihre Entscheidungen öffentlich diskutieren.", "tip": "Parlament und Regierung sind nicht dasselbe."}, {"id": "l110", "subject": "Politik", "grade": 7, "title": "Parteien und Interessenverbände", "explain": ["Parteien bündeln politische Positionen und wollen durch Wahlen politische Verantwortung übernehmen.", "Verbände vertreten bestimmte Interessen, etwa von Beschäftigten, Unternehmen oder Umweltinitiativen."], "example": "Ein Verband setzt sich für ein Anliegen ein. Eine Partei verbindet mehrere Themen zu einem politischen Programm.", "tip": "Prüfe, welche Interessen vertreten werden und welche möglicherweise fehlen."}, {"id": "l111", "subject": "Politik", "grade": 7, "title": "Wirtschaft: Angebot und Nachfrage", "explain": ["Auf Märkten treffen Angebot und Nachfrage zusammen. Preise können sich verändern, wenn Güter knapper oder stärker nachgefragt werden.", "Preise hängen aber auch von Kosten, Regeln, Wettbewerb und Marktmacht ab."], "example": "Wenn ein beliebtes Produkt knapp wird, kann sein Preis steigen. Das ist keine Garantie für jeden Einzelfall.", "tip": "Ein einfaches Marktmodell erklärt Zusammenhänge, nicht sämtliche realen Einflüsse."}, {"id": "l112", "subject": "Politik", "grade": 8, "title": "Soziale Marktwirtschaft", "explain": ["Eine soziale Marktwirtschaft verbindet wirtschaftlichen Wettbewerb mit staatlichen Regeln und sozialem Ausgleich.", "Politisch umstritten ist oft, wie viel Regulierung und Absicherung sinnvoll sind."], "example": "Regeln können Wettbewerb schützen; soziale Sicherung kann bestimmte Lebensrisiken abfedern.", "tip": "Beurteile Maßnahmen nach mehreren Kriterien, etwa Freiheit, Sicherheit, Gerechtigkeit und Kosten."}, {"id": "l113", "subject": "Politik", "grade": 8, "title": "Die Europäische Union", "explain": ["Die EU ist ein Zusammenschluss europäischer Staaten mit gemeinsamen Institutionen und vereinbarten Zuständigkeiten.", "Mitgliedstaaten arbeiten etwa beim Binnenmarkt zusammen. Nicht alle europäischen Staaten sind EU-Mitglieder, und nicht alle EU-Staaten nutzen den Euro."], "example": "Eine Ware kann im gemeinsamen Binnenmarkt unter gemeinsamen Regeln leichter grenzüberschreitend gehandelt werden.", "tip": "Europa, EU und Euro-Raum bezeichnen unterschiedliche Dinge."}, {"id": "l114", "subject": "Politik", "grade": 8, "title": "Menschenrechte und Grundrechte", "explain": ["Menschenrechte gelten ihrem Anspruch nach für alle Menschen. Grundrechte sind besonders geschützte Rechte in einer staatlichen Verfassungsordnung.", "Rechte schützen unter anderem Freiheit, Gleichheit und Würde. Wenn Rechte miteinander in Konflikt geraten, braucht es eine sorgfältige rechtliche Abwägung."], "example": "Freiheit der Meinungsäußerung ist wichtig, bedeutet aber keinen grenzenlosen Freiraum für jede Handlung.", "tip": "Rechte gehören auch Menschen, deren Meinung man ablehnt."}, {"id": "l115", "subject": "Politik", "grade": 9, "title": "Politische Urteile begründen", "explain": ["Ein politisches Urteil braucht mehr als ein spontanes Dafür oder Dagegen. Kläre die Frage, Fakten, Interessen und Bewertungskriterien.", "Wäge Handlungsoptionen und Folgen ab. Zeige, welche Werte dein Urteil prägen."], "example": "Eine Verkehrsmaßnahme kann nach Sicherheit, Kosten, Umweltwirkung und Zugänglichkeit bewertet werden.", "tip": "Unterscheide zwischen „Ist eine Maßnahme wirksam?“ und „Ist sie gerechtfertigt?“."}, {"id": "l116", "subject": "Politik", "grade": 9, "title": "Globalisierung", "explain": ["Globalisierung beschreibt zunehmende weltweite Verflechtungen, etwa durch Handel, Kommunikation, Kapital und Migration.", "Sie kann neue Möglichkeiten schaffen, aber auch Abhängigkeiten und ungleich verteilte Belastungen."], "example": "Ein Handy kann Rohstoffe, Bauteile und Arbeit aus vielen Ländern verbinden.", "tip": "Frage immer: Wer profitiert, wer trägt Risiken, und unter welchen Bedingungen?"}, {"id": "l117", "subject": "Politik", "grade": 9, "title": "Desinformation und Algorithmen", "explain": ["Desinformation bezeichnet absichtlich verbreitete irreführende oder falsche Informationen. Nicht jeder Fehler ist absichtlich.", "Empfehlungssysteme wählen Inhalte nach bestimmten Zielen aus. Häufige Anzeige ist kein Wahrheitsbeweis."], "example": "Ein emotionales Video kann oft empfohlen werden, obwohl wichtige Zusammenhänge fehlen.", "tip": "Prüfe Originalquelle, Datum, Kontext und unabhängige Bestätigung."}, {"id": "l118", "subject": "Politik", "grade": 10, "title": "Demokratie unter Druck", "explain": ["Demokratische Systeme brauchen faire Verfahren, unabhängige Kontrolle, geschützte Rechte und politische Beteiligung.", "Gefährdungen können entstehen, wenn Machtkontrolle ausgehöhlt, Gruppen entrechtet oder Gewalt als politisches Mittel eingesetzt wird."], "example": "Kritik an Regierungspolitik ist demokratische Normalität. Die Abschaffung freier Wahlen wäre etwas grundsätzlich anderes.", "tip": "Unterscheide Kritik innerhalb demokratischer Regeln von Angriffen auf diese Regeln."}, {"id": "l119", "subject": "Politik", "grade": 10, "title": "Frieden und internationale Zusammenarbeit", "explain": ["Staaten und internationale Organisationen versuchen, Konflikte durch Verhandlungen, Regeln und Zusammenarbeit zu bearbeiten.", "Interessen, Machtunterschiede und fehlende Durchsetzungsmöglichkeiten können Lösungen erschweren."], "example": "Ein Vermittlungsversuch sucht zunächst verhandelbare Interessen und Bedingungen, denen Konfliktparteien zustimmen können.", "tip": "Eine Erklärung von Konfliktursachen ist keine Rechtfertigung von Gewalt."}, {"id": "l120", "subject": "Politik", "grade": 10, "title": "Nachhaltigkeit politisch abwägen", "explain": ["Nachhaltige Politik betrachtet ökologische, soziale und wirtschaftliche Folgen sowie zukünftige Generationen.", "Zwischen Zielen können Konflikte entstehen. Vergleiche Maßnahmen, Kosten, Verteilung und langfristige Wirkung."], "example": "Eine Klimaschutzmaßnahme kann Emissionen mindern und zugleich Haushalte unterschiedlich belasten. Ausgleichsmaßnahmen können Teil der Lösung sein.", "tip": "Benutze überprüfbare Daten und lege deine Bewertungskriterien offen."}, {"id": "l121", "subject": "Erdkunde", "grade": 1, "title": "Wo bin ich?", "explain": ["Orte kannst du mit Wörtern wie links, rechts, vor und hinter beschreiben. Die Richtung hängt davon ab, wohin du schaust.", "Mit markanten Punkten kannst du dir einen Weg merken."], "example": "Vom Klassenzimmer gehst du bis zur Treppe und dann zur großen Tür.", "tip": "Links und rechts können sich ändern, wenn du dich umdrehst."}, {"id": "l122", "subject": "Erdkunde", "grade": 1, "title": "Das Wetter beobachten", "explain": ["Wetter ist das, was draußen gerade in der Luft passiert: Sonne, Wolken, Regen, Wind oder Schnee.", "Du kannst verschiedene Merkmale einzeln beschreiben."], "example": "Heute ist es bewölkt, windig und kühl. Es kann bewölkt sein, ohne dass es regnet.", "tip": "Ein Thermometer misst die Temperatur; dein Gefühl allein ist keine genaue Messung."}, {"id": "l123", "subject": "Erdkunde", "grade": 1, "title": "Die vier Jahreszeiten", "explain": ["Frühling, Sommer, Herbst und Winter kehren jedes Jahr wieder. Bei uns verändern sich dabei oft Wetter, Pflanzen und Tageslänge.", "Nicht jeder Tag einer Jahreszeit ist gleich."], "example": "Im Winter sind die Tage bei uns meist kürzer als im Sommer. Ein sonniger Wintertag kann trotzdem kalt sein.", "tip": "Jahreszeiten sind typische Abschnitte des Jahres, keine genaue Wettervorhersage."}, {"id": "l124", "subject": "Erdkunde", "grade": 2, "title": "Ein Plan von oben", "explain": ["Ein Plan zeigt einen Ort vereinfacht von oben. Dinge werden durch Zeichen dargestellt.", "Eine Legende erklärt, was die Zeichen bedeuten."], "example": "Ein blaues Rechteck kann im Schwimmbadplan ein Becken zeigen. Die Legende hilft dir beim Lesen.", "tip": "Ein Plan zeigt nur ausgewählte Dinge, nicht jedes Detail."}, {"id": "l125", "subject": "Erdkunde", "grade": 2, "title": "Stadt und Dorf", "explain": ["In Städten leben meist mehr Menschen dichter zusammen als in Dörfern. Es gibt verschiedene Formen von Wohnorten.", "Auch Dörfer haben Arbeitsplätze und Städte Grünflächen. Übergänge können fließend sein."], "example": "Ein Dorf kann von Feldern umgeben sein; eine Stadt kann einen großen Park besitzen.", "tip": "Vergleiche konkrete Merkmale statt nur „groß“ und „klein“."}, {"id": "l126", "subject": "Erdkunde", "grade": 2, "title": "Wasser in unserer Umgebung", "explain": ["Wasser findest du etwa in Bächen, Flüssen, Seen, im Boden und in der Luft.", "Flüsse fließen dem Gefälle folgend. Ein See sammelt Wasser in einer Vertiefung."], "example": "Ein kleiner Bach kann in einen Fluss münden. Der Fluss kann schließlich das Meer erreichen.", "tip": "Wasser bewegt sich nicht nur sichtbar an der Oberfläche."}, {"id": "l127", "subject": "Erdkunde", "grade": 3, "title": "Himmelsrichtungen", "explain": ["Norden, Osten, Süden und Westen helfen beim Orientieren. Ein Kompass unterstützt dich dabei.", "Auf vielen Karten ist Norden oben; prüfe trotzdem den Nordpfeil."], "example": "Wenn Norden auf deiner Karte oben ist, liegt Osten rechts und Westen links.", "tip": "„Oben auf dem Blatt“ bedeutet nur dann Norden, wenn die Karte so ausgerichtet ist."}, {"id": "l128", "subject": "Erdkunde", "grade": 3, "title": "Der Wasserkreislauf", "explain": ["Wasser verdunstet, steigt als Wasserdampf auf und kann beim Abkühlen zu winzigen Tropfen oder Eiskristallen werden.", "Daraus entstehen Wolken. Niederschlag gelangt auf die Erde; Wasser versickert oder fließt ab."], "example": "Eine Pfütze trocknet: Wasser ist verdunstet. Es wurde nicht einfach vernichtet.", "tip": "Wasserdampf selbst ist unsichtbar; Wolken bestehen aus kleinen Tropfen oder Eiskristallen."}, {"id": "l129", "subject": "Erdkunde", "grade": 3, "title": "Landschaften beschreiben", "explain": ["Landschaften unterscheiden sich durch Gelände, Wasser, Pflanzen und menschliche Nutzung.", "Du kannst natürliche Merkmale und vom Menschen geschaffene Merkmale unterscheiden."], "example": "Ein Tal mit Fluss ist ein Geländemerkmal. Straßen, Felder und Häuser zeigen menschliche Nutzung.", "tip": "Viele heutige Landschaften wurden über lange Zeit vom Menschen verändert."}, {"id": "l130", "subject": "Erdkunde", "grade": 4, "title": "Deutschland auf der Karte", "explain": ["Deutschland liegt in Europa. Auf Karten findest du unter anderem Bundesländer, Städte, Flüsse und Gebirge.", "Eine politische Karte zeigt andere Informationen als eine Karte der Höhen."], "example": "Berlin ist die Hauptstadt Deutschlands. Der Rhein ist ein großer Fluss; die Alpen liegen im Süden Deutschlands und in weiteren Ländern.", "tip": "Lies zuerst Titel und Legende, damit du weißt, welche Karte du anschaust."}, {"id": "l131", "subject": "Erdkunde", "grade": 4, "title": "Kontinente und Ozeane", "explain": ["Kontinente sind große Landräume. Ozeane bilden die großen zusammenhängenden Meeresräume.", "In einem verbreiteten Modell unterscheidet man sieben Kontinente. Andere Modelle fassen einige zusammen."], "example": "Europa und Asien sind zusammenhängendes Land und werden auch als Eurasien betrachtet.", "tip": "Die Zahl der Kontinente hängt vom verwendeten Modell ab."}, {"id": "l132", "subject": "Erdkunde", "grade": 4, "title": "Maßstab verstehen", "explain": ["Ein Maßstab sagt, wie stark eine Darstellung verkleinert ist. Bei 1 : 100 entspricht 1 cm auf dem Plan 100 cm in Wirklichkeit.", "Rechne zuerst in derselben Einheit und wandle danach um."], "example": "Bei 1 : 1.000 entsprechen 2 cm auf dem Plan 2.000 cm, also 20 m.", "tip": "Eine Luftlinie auf der Karte ist nicht automatisch die Länge des tatsächlichen Weges."}, {"id": "l133", "subject": "Erdkunde", "grade": 5, "title": "Gradnetz der Erde", "explain": ["Breiten- und Längengrade helfen, Orte auf der Erde anzugeben. Der Äquator hat 0° Breite.", "Breiten werden nach Norden oder Süden angegeben, Längen nach Osten oder Westen vom Nullmeridian."], "example": "Ein Punkt bei 20° N liegt nördlich des Äquators. 20° S liegt südlich davon.", "tip": "Breite sagt Nord oder Süd; Länge sagt Ost oder West."}, {"id": "l134", "subject": "Erdkunde", "grade": 5, "title": "Höhenlinien lesen", "explain": ["Höhenlinien verbinden Punkte gleicher Höhe. Ihr Abstand zeigt, wie steil das Gelände ungefähr ist.", "Eng beieinanderliegende Linien bedeuten bei gleichem Höhenabstand einen steilen Hang."], "example": "Steigt die Höhe auf kurzer Kartenstrecke von 200 m auf 300 m, ist es steiler als bei derselben Höhendifferenz auf langer Strecke.", "tip": "Prüfe den angegebenen Höhenabstand zwischen den Linien."}, {"id": "l135", "subject": "Erdkunde", "grade": 5, "title": "Landwirtschaft und Standort", "explain": ["Landwirtschaft hängt unter anderem von Boden, Wasser, Klima, Technik und Absatzmöglichkeiten ab.", "Menschen verändern Standorte etwa durch Bewässerung oder Düngung. Das kann Nutzen und Umweltfolgen haben."], "example": "Eine Pflanze mit hohem Wasserbedarf passt ohne Bewässerung schlecht zu einem sehr trockenen Standort.", "tip": "Erkläre Standorte mit mehreren Faktoren, nicht nur mit dem Wetter."}, {"id": "l136", "subject": "Erdkunde", "grade": 6, "title": "Wetter und Klima", "explain": ["Wetter beschreibt den aktuellen Zustand der Atmosphäre. Klima beschreibt typische Verhältnisse und Schwankungen über lange Zeiträume.", "Für Klimavergleiche werden häufig Zeiträume von 30 Jahren betrachtet."], "example": "Ein kalter Tag beschreibt Wetter. Eine langfristige Veränderung durchschnittlicher Temperaturen betrifft Klima.", "tip": "Ein einzelner Tag bestätigt oder widerlegt keinen langfristigen Klimatrend."}, {"id": "l137", "subject": "Erdkunde", "grade": 6, "title": "Warum gibt es Jahreszeiten?", "explain": ["Die Erdachse ist geneigt. Während die Erde die Sonne umkreist, ändern sich Sonnenstand und Tageslänge auf den Halbkugeln.", "Ist die Nordhalbkugel der Sonne zugeneigt, ist dort Sommer und auf der Südhalbkugel Winter."], "example": "Ein höherer Sonnenstand verteilt dieselbe Strahlung auf eine kleinere Fläche; längere Tage ermöglichen mehr Erwärmung.", "tip": "Unsere Jahreszeiten entstehen hauptsächlich durch die Achsneigung, nicht durch wechselnde Entfernung zur Sonne."}, {"id": "l138", "subject": "Erdkunde", "grade": 6, "title": "Tourismus und seine Folgen", "explain": ["Tourismus schafft Einkommen und Arbeitsplätze. Er beansprucht aber auch Raum, Wasser, Energie und Verkehr.", "Die Folgen hängen von Umfang, Ort und Art des Reisens ab."], "example": "Ein Küstenort kann von Gästen leben und zugleich unter Verkehr, Müll oder hohen Wohnungspreisen leiden.", "tip": "Betrachte die Perspektiven von Gästen, Beschäftigten und Einheimischen."}, {"id": "l139", "subject": "Erdkunde", "grade": 7, "title": "Plattentektonik", "explain": ["Die feste äußere Hülle der Erde besteht aus Platten, die sich langsam gegeneinander bewegen.", "An ihren Grenzen können Gebirge, Erdbeben und Vulkanismus entstehen. Nicht jede Grenze funktioniert gleich."], "example": "Platten können auseinanderdriften, aneinander vorbeigleiten oder aufeinander zuwandern.", "tip": "Erdplatten bewegen sich sehr langsam, doch Spannungen können plötzlich freiwerden."}, {"id": "l140", "subject": "Erdkunde", "grade": 7, "title": "Klimadiagramme lesen", "explain": ["Ein Klimadiagramm zeigt meist Monatsmittel der Temperatur und monatliche Niederschlagssummen für einen längeren Zeitraum.", "Lies Achsen, Einheiten, Ort und Bezugszeitraum. Vergleiche dann Jahresgang und Verteilung."], "example": "Eine hohe Jahresniederschlagssumme sagt noch nicht, ob es gleichmäßig regnet oder eine lange Trockenzeit gibt.", "tip": "Temperatur- und Niederschlagsachsen können unterschiedlich skaliert sein."}, {"id": "l141", "subject": "Erdkunde", "grade": 7, "title": "Leben in trockenen Räumen", "explain": ["In trockenen Räumen steht wenig Wasser zur Verfügung. Niederschlag, Verdunstung, Boden und Nutzung beeinflussen die Situation.", "Anpassungen können Wasserspeicherung, angepasste Pflanzen und sparsame Bewässerung sein."], "example": "Bewässerung ermöglicht Anbau, kann bei ungünstigen Bedingungen aber zur Versalzung des Bodens beitragen.", "tip": "Wüste bedeutet vor allem große Trockenheit; nicht jede Wüste besteht aus Sand."}, {"id": "l142", "subject": "Erdkunde", "grade": 8, "title": "Bevölkerung und Migration", "explain": ["Bevölkerungszahlen verändern sich durch Geburten, Sterbefälle, Zu- und Abwanderung.", "Migration hat vielfältige Gründe, etwa Arbeit, Familie, Ausbildung, Verfolgung oder Krieg."], "example": "Ein Ort kann trotz weniger Geburten wachsen, wenn mehr Menschen zu- als fortziehen.", "tip": "Ein einzelner Grund erklärt selten alle Wanderungsentscheidungen."}, {"id": "l143", "subject": "Erdkunde", "grade": 8, "title": "Städte wachsen und verändern sich", "explain": ["Urbanisierung beschreibt unter anderem den wachsenden Anteil der Stadtbevölkerung. Stadtwachstum braucht Wohnungen, Infrastruktur und Versorgung.", "Ungeplantes Wachstum kann Verkehrs-, Umwelt- und Versorgungsprobleme verstärken."], "example": "Ein neuer Stadtteil braucht nicht nur Häuser, sondern auch Wege, Schulen, Wasser und Grünflächen.", "tip": "Mehr bebaute Fläche ist nicht automatisch bessere Lebensqualität."}, {"id": "l144", "subject": "Erdkunde", "grade": 8, "title": "Tropischer Regenwald", "explain": ["Tropische Regenwälder wachsen in ganzjährig warmen, niederschlagsreichen Regionen. Sie haben eine hohe Artenvielfalt.", "Viele Nährstoffe sind in der lebenden Biomasse gebunden und werden schnell im Kreislauf umgesetzt. Böden sind nicht automatisch dauerhaft fruchtbar."], "example": "Nach Rodung kann ein Boden durch Auswaschung und Erosion schnell an Fruchtbarkeit verlieren.", "tip": "Ein üppiger Wald bedeutet nicht zwangsläufig einen besonders nährstoffreichen Boden."}, {"id": "l145", "subject": "Erdkunde", "grade": 9, "title": "Treibhauseffekt und Klimawandel", "explain": ["Treibhausgase absorbieren und emittieren Wärmestrahlung. Der natürliche Treibhauseffekt macht die Erde deutlich wärmer, als sie ohne ihn wäre.", "Zusätzliche Treibhausgase durch menschliche Aktivitäten verstärken die Erwärmung und verändern das Klimasystem."], "example": "Die Verbrennung fossiler Energieträger setzt CO₂ frei. Mehr CO₂ verändert die Strahlungsbilanz der Erde.", "tip": "Der Treibhauseffekt ist nicht dasselbe wie das Ozonloch."}, {"id": "l146", "subject": "Erdkunde", "grade": 9, "title": "Entwicklung vergleichen", "explain": ["Lebensbedingungen lassen sich nicht mit einer einzigen Zahl vollständig beschreiben. Einkommen, Bildung, Gesundheit und Ungleichheit liefern unterschiedliche Hinweise.", "Durchschnittswerte können große Unterschiede innerhalb eines Landes verdecken."], "example": "Ein hohes Durchschnittseinkommen sagt wenig darüber, wie das Einkommen verteilt ist.", "tip": "Vergleiche mehrere Indikatoren und vermeide pauschale Aussagen über ganze Bevölkerungen."}, {"id": "l147", "subject": "Erdkunde", "grade": 9, "title": "Globale Lieferketten", "explain": ["Produkte durchlaufen oft viele Länder: Rohstoffgewinnung, Verarbeitung, Montage und Verkauf können getrennt stattfinden.", "Transport, Arbeitsbedingungen, Wertschöpfung und Umweltfolgen sind ungleich verteilt."], "example": "Ein T-Shirt kann Baumwolle aus einem Land, Stoffproduktion aus einem zweiten und Konfektion aus einem dritten verbinden.", "tip": "Der Verkaufspreis zeigt nicht direkt, welcher Anteil bei den einzelnen Beteiligten ankommt."}, {"id": "l148", "subject": "Erdkunde", "grade": 10, "title": "Nachhaltige Stadtentwicklung", "explain": ["Nachhaltige Stadtentwicklung verbindet Wohnen, Mobilität, Wirtschaft, soziale Teilhabe und Umweltqualität.", "Maßnahmen können kurze Wege, Grünflächen, bezahlbares Wohnen und gut erreichbaren öffentlichen Verkehr unterstützen."], "example": "Bäume und entsiegelte Flächen können Regenwasser zurückhalten und zur Kühlung beitragen; sie brauchen Platz und Pflege.", "tip": "Bewerte Maßnahmen auch danach, wem sie nützen und wen sie belasten."}, {"id": "l149", "subject": "Erdkunde", "grade": 10, "title": "Naturgefahren und Risiken", "explain": ["Eine Naturgefahr wird für Menschen zum Risiko, wenn gefährdete Personen oder Sachwerte betroffen sein können.", "Das Risiko hängt von Gefahr, Exposition und Verletzlichkeit ab. Vorsorge kann Schäden verringern."], "example": "Gleich starke Hochwasser können je nach Bebauung, Warnsystem und Schutzmaßnahmen sehr unterschiedliche Folgen haben.", "tip": "Ein Naturereignis allein erklärt noch nicht das Ausmaß einer Katastrophe."}, {"id": "l150", "subject": "Erdkunde", "grade": 10, "title": "Räume und Karten kritisch beurteilen", "explain": ["Karten wählen Informationen aus und stellen sie in einer bestimmten Form dar. Projektion, Farben, Klassen und Maßstab beeinflussen den Eindruck.", "Prüfe Datenquelle, Bezugsjahr und Darstellung. Flächengröße und Bevölkerungszahl sind unterschiedliche Bezugsgrößen."], "example": "Eine Karte absoluter Fallzahlen kann bevölkerungsreiche Gebiete stark hervorheben. Werte pro Einwohner beantworten eine andere Frage.", "tip": "Eine Karte ist ein Modell mit einem Zweck, kein neutrales Abbild sämtlicher Wirklichkeit."}];
